// src/ar/ar-perf-stats.js
function createPerfStatsCollector(opts = {}) {
  let frames = 0;
  let lastT = 0;
  let fps = 0;
  let ms = 0;
  function sampleLines() {
    const lines = [];
    lines.push(fps > 0 ? `${Math.round(fps)} FPS` : "\u2014 FPS");
    lines.push(ms > 0 ? `${ms.toFixed(1)} ms` : "\u2014 ms");
    try {
      const n = opts.getSplatCount?.();
      lines.push(typeof n === "number" && n > 0 ? `${n.toLocaleString()} splats` : "splats \u2014");
    } catch (_) {
      lines.push("splats \u2014");
    }
    try {
      const info = opts.getRenderer?.()?.info;
      const calls = info?.render?.calls;
      const tris = info?.render?.triangles;
      lines.push(calls != null && tris != null ? `draw ${calls} \xB7 ${Math.round(tris).toLocaleString()} tris` : "draw \u2014");
    } catch (_) {
      lines.push("draw \u2014");
    }
    try {
      const mem = performance.memory;
      if (mem?.usedJSHeapSize) {
        const used = mem.usedJSHeapSize / 1048576;
        const lim = mem.jsHeapSizeLimit / 1048576;
        lines.push(lim ? `heap ${used.toFixed(0)} / ${lim.toFixed(0)} MB` : `heap ${used.toFixed(0)} MB`);
      } else {
        lines.push("heap n/a");
      }
    } catch (_) {
      lines.push("heap n/a");
    }
    return lines;
  }
  return {
    get fps() {
      return fps;
    },
    get ms() {
      return ms;
    },
    lines() {
      return sampleLines();
    },
    tick(now = performance.now()) {
      if (!lastT) lastT = now;
      frames += 1;
      const elapsed = now - lastT;
      if (elapsed >= 400) {
        fps = frames * 1e3 / elapsed;
        ms = elapsed / frames;
        frames = 0;
        lastT = now;
        return true;
      }
      return false;
    }
  };
}

// src/ar/ar-perf-hud.js
var STORAGE_KEY2 = "ar-perf-hud-visible";
