// src/ar/ar-hud.js
function createARBottomHud({
  showMovie = true,
  showMovieAudio = true,
  showPerf = true,
  showExit = true,
  exitLabel = "Exit"
} = {}) {
  const hud = document.createElement("div");
  hud.className = "ar-xr-hud";
  const movieBtns = showMovie ? `<button type="button" class="ar-xr-btn ar-xr-play">Play</button>` : "";
  const exitBtn = showExit ? `<button type="button" class="ar-xr-btn ar-xr-stop">${exitLabel}</button>` : "";
  ensureARAudioMuteIconStyles();
  hud.innerHTML = `
    <p class="ar-xr-status"></p>
    <div class="ar-xr-hud-actions">
      ${movieBtns}
      ${showPerf ? arPerfToggleButtonHtml() : ""}
      ${exitBtn}
    </div>`;
  document.body.appendChild(hud);
  if (showMovieAudio) {
    let muteBtn = typeof document !== "undefined" ? document.querySelector(`.${AR_AUDIO_MUTE_BTN_CLASS}`) : null;
    let owned = false;
    if (!muteBtn) {
      const wrap = document.createElement("div");
      wrap.innerHTML = arAudioMuteIconHtml({ muted: true });
      muteBtn = wrap.firstElementChild;
      document.body.appendChild(muteBtn);
      owned = true;
    } else {
      try {
        muteBtn.hidden = false;
      } catch (_) {
      }
      try {
        muteBtn.removeAttribute("hidden");
      } catch (_) {
      }
    }
    hud._arMuteBtn = muteBtn;
    hud._arMuteOwned = owned;
    hud._arMuteUnpin = pinARAudioMuteIcon(muteBtn);
    const origRemove = hud.remove.bind(hud);
    hud.remove = () => {
      try {
        hud._arMuteUnpin?.();
      } catch (_) {
      }
      if (hud._arMuteOwned) {
        try {
          hud._arMuteBtn?.remove();
        } catch (_) {
        }
      }
      origRemove();
    };
  }
  return hud;
}

